import heapq, random, math
random.seed(3)
N, D = 400, 8
vecs = [[random.gauss(0, 1) for _ in range(D)] for _ in range(N)]

def dist(a, b):
    return math.sqrt(sum((x-y)**2 for x, y in zip(a, b)))

g = {}
for i, v in enumerate(vecs):
    g[i] = [j for _, j in heapq.nsmallest(10, ((dist(v, u), j) for j, u in enumerate(vecs) if j != i))]

def beam_search(q, ef):
    cand = [(dist(vecs[0], q), 0)]  # min-heap of candidates
    visited = {0}
    best = []  # max-heap via -d: keeps the ef closest
    while cand:
        d, n = heapq.heappop(cand)
        if len(best) >= ef and d >= -best[0][0]:
            break
        for m in g[n]:
            if m not in visited:
                visited.add(m)
                dm = dist(vecs[m], q)
                heapq.heappush(cand, (dm, m))
                if len(best) < ef:
                    heapq.heappush(best, (-dm, m))
                elif dm < -best[0][0]:
                    heapq.heapreplace(best, (-dm, m))
    return [m for _, m in best], len(visited)

q = [random.gauss(0, 1) for _ in range(D)]
truth = set(sorted(range(N), key=lambda i: dist(vecs[i], q))[:10])
for ef in (1, 10, 50):
    ids, visited = beam_search(q, ef)
    print('ef=%2d visited=%3d recall@10=%.2f' % (ef, visited, len(set(ids) & truth) / 10))

import random
from collections import Counter
random.seed(5)
# DeepWalk sketch: random walks -> co-occurrence -> 'embedding' via counts
g = {0: [1, 2], 1: [0, 2, 3], 2: [0, 1], 3: [1, 4], 4: [3]}

def walk(s, L=6):
    p = [s]
    for _ in range(L):
        p.append(random.choice(g[p[-1]]))
    return p

co = Counter()
for _ in range(2000):
    w = walk(random.choice(list(g)))
    for i, a in enumerate(w):
        for b in w[max(0, i-2):i+3]:
            if a != b:
                co[(a, b)] += 1

def sim(a, b):
    return co[(a, b)] + co[(b, a)]

print('co-occurrence with node 1:', {n: sim(1, n) for n in g if n != 1})
print('neighbors co-occur most: structure became measurable similarity')

from collections import deque

g = {'a': ['b', 'c'], 'b': ['d'], 'c': ['d'], 'd': []}

def bfs(s, t):
    q, seen = deque([(s, [s])]), {s}
    while q:
        n, path = q.popleft()
        if n == t:
            return path
        for m in g[n]:
            if m not in seen:
                seen.add(m)
                q.append((m, path + [m]))

def dfs(s, seen=None, order=None):
    seen = seen or set(); order = order or []
    seen.add(s); order.append(s)
    for m in g[s]:
        if m not in seen:
            dfs(m, seen, order)
    return order

print('BFS a->d (shortest):', bfs('a', 'd'))
print('DFS from a:', dfs('a'))

from collections import Counter
# label propagation: adopt your neighbors' majority label
g = {0: [1, 2], 1: [0, 2], 2: [0, 1, 3], 3: [2, 4, 5], 4: [3, 5], 5: [3, 4]}
label = {n: n for n in g}

